record.field:
try:
    cfg = json.loads(self.remote_id.connection_params or '{}') or {}
except Exception:
    cfg = {}
api_key = (cfg.get('api_key') or '').strip()
username = (cfg.get('username') or '').strip()
password = cfg.get('password') or ''
if not all([api_key, username, password]):
    raise Exception('Missing Netilion api_key, username or password.')
headers = {
    'API-Key': api_key,
    'Authorization': 'Basic %s' % base64.b64encode('%s:%s' % (username, password)),
    'Accept': 'application/json',
}
resp = request_retry('GET', (base_url or '').rstrip('/') + '/v1/users/current', headers=headers, timeout=timeout)
if resp.status_code >= 400:
    raise Exception('Netilion credentials validation failed: %s %s' % (
        resp.status_code, resp.text))
bag['netilion_headers'] = headers
bag['netilion_user'] = resp.json() or {}

headers = bag.get('netilion_headers') or {}
if not headers:
    raise Exception("Missing Netilion credentials in bag. Run 'Validate Credentials' first.")
assets = []
page = 1
while True:
    url = '%s/v1/assets?page=%s&per_page=100' % ((base_url or '').rstrip('/'), page)
    resp = request_retry('GET', url, headers=headers, timeout=timeout)
    if resp.status_code >= 400:
        raise Exception('GET /v1/assets failed: %s %s' % (resp.status_code, resp.text))
    payload = resp.json() or {}
    records = payload.get('assets', [])
    if not isinstance(records, list):
        raise Exception('Unexpected Netilion assets response: %s' % payload)
    assets.extend(records)
    pagination = payload.get('pagination') or {}
    if page >= int(pagination.get('page_count') or page):
        break
    page += 1
content = json.dumps({'executed_at': fields.Datetime.now(), 'assets': assets},
    ensure_ascii=False, indent=2).encode('utf-8')
fname = 'netilion_assets_%s.json' % fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
att = env['ir.attachment'].create({
    'name': fname, 'datas_fname': fname, 'datas': base64.b64encode(content),
    'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': self.remote_id.id,
})
self.remote_id.message_post(body=u'[Netilion] assets=%s' % len(assets), attachment_ids=[att.id])
bag['assets'] = assets
bag['assets_attachment_id'] = att.id

from urllib import urlencode

headers = bag.get('netilion_headers') or {}
if not headers:
    raise Exception("Missing Netilion credentials in bag. Run 'Validate Credentials' first.")
try:
    cfg = json.loads(self.remote_id.connection_params or '{}') or {}
except Exception:
    cfg = {}
asset_id = cfg.get('history_asset_id')
key = cfg.get('history_key')
if not asset_id or not key:
    raise Exception('Set history_asset_id and history_key in connection_params.')
params = {'page': 1, 'per_page': 100}
if cfg.get('history_from'):
    params['from'] = cfg['history_from']
if cfg.get('history_to'):
    params['to'] = cfg['history_to']
url = '%s/v1/assets/%s/values/%s?%s' % (
    (base_url or '').rstrip('/'), asset_id, key, urlencode(params))
resp = request_retry('GET', url, headers=headers, timeout=timeout)
if resp.status_code >= 400:
    raise Exception('GET Netilion variable history failed: %s %s' % (resp.status_code, resp.text))
content = json.dumps(resp.json() or [], ensure_ascii=False, indent=2).encode('utf-8')
fname = 'netilion_history_%s_%s.json' % (asset_id, key)
att = env['ir.attachment'].create({
    'name': fname, 'datas_fname': fname, 'datas': base64.b64encode(content),
    'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': self.remote_id.id,
})
self.remote_id.message_post(body=u'[Netilion] history asset=%s key=%s' % (asset_id, key), attachment_ids=[att.id])
bag['history_attachment_id'] = att.id

condition = [('remotecontrol_params', '!=', False), ('device_id.remotecontrol_id', '=', self.remote_id.id)]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
plan = []
for sensor in env['mdm.measurement.device.sensor'].search(condition):
    try:
        device_cfg = json.loads(sensor.device_id.remotecontrol_params or '{}') or {}
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        continue
    asset_id = device_cfg.get('asset_id')
    key = sensor_cfg.get('key')
    if asset_id and key:
        plan.append({'sensor_id': sensor.id, 'device_id': sensor.device_id.id,
                     'asset_id': asset_id, 'key': key})
bag['sensors_plan'] = plan

headers = bag.get('netilion_headers') or {}
if not headers:
    raise Exception("Missing Netilion credentials in bag. Run 'Validate Credentials' first.")
plans_by_asset = {}
for plan in bag.get('sensors_plan') or []:
    plans_by_asset.setdefault(str(plan['asset_id']), []).append(plan)
items = []
total_upserts = 0
total_errors = 0
for asset_id, asset_plans in plans_by_asset.items():
    try:
        values = []
        page = 1
        while True:
            url = '%s/v1/assets/%s/values?include=unit&page=%s&per_page=100' % ((base_url or '').rstrip('/'), asset_id, page)
            resp = request_retry('GET', url, headers=headers, timeout=timeout)
            if resp.status_code >= 400:
                raise Exception('%s %s' % (resp.status_code, resp.text))
            payload = resp.json() or {}
            records = payload.get('values', [])
            if not isinstance(records, list):
                raise Exception('Unexpected Netilion values response: %s' % payload)
            values.extend(records)
            pagination = payload.get('pagination') or {}
            if page >= int(pagination.get('page_count') or page):
                break
            page += 1
        values_by_key = dict((record.get('key'), record) for record in values if record.get('key'))
        for plan in asset_plans:
            record = values_by_key.get(plan['key']) or {}
            value = record.get('value')
            timestamp = record.get('timestamp') or record.get('time') or record.get('created_at') or ''
            if value in (None, '') or not timestamp:
                raise Exception('Missing value or timestamp for key %s' % plan['key'])
            date_iso = timestamp.replace('T', ' ').replace('Z', '')[:19]
            fields.Datetime.from_string(date_iso)
            with env.cr.savepoint():
                self.remote_id.with_context(
                    disable_test_create_reading=True).upsert(
                    'mdm.measurement.device.sensor.reading',
                    {'sensor_id': plan['sensor_id'], 'measurement_time': date_iso},
                    {'value': float(value), 'device_id': plan['device_id']})
            total_upserts += 1
            items.append({'asset_id': asset_id, 'sensor_id': plan['sensor_id'],
                          'key': plan['key'], 'value': float(value),
                          'date': date_iso, 'unit': record.get('unit')})
    except Exception as error:
        total_errors += len(asset_plans)
        for plan in asset_plans:
            items.append({'asset_id': asset_id, 'sensor_id': plan['sensor_id'],
                          'key': plan['key'], 'error': str(error)})
def to_unicode(value):
    if isinstance(value, str):
        return value.decode('utf-8', 'replace')
    if isinstance(value, list):
        return [to_unicode(item) for item in value]
    if isinstance(value, dict):
        return dict((to_unicode(key), to_unicode(item))
                    for key, item in value.items())
    return value

content = json.dumps(to_unicode({
    'executed_at': fields.Datetime.now(), 'total_upserts': total_upserts,
    'total_errors': total_errors, 'items': items}), ensure_ascii=False, indent=2).encode('utf-8')
fname = 'netilion_readings_%s.json' % fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
att = env['ir.attachment'].create({
    'name': fname, 'datas_fname': fname, 'datas': base64.b64encode(content),
    'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': self.remote_id.id,
})
self.remote_id.message_post(body=u'[Netilion] upserts=%s errors=%s' % (total_upserts, total_errors), attachment_ids=[att.id])
bag['upserts'] = total_upserts
bag['errors'] = total_errors
